-- submissions/lock
-- Locks one submission for the rest of the transaction, so two reviewers deciding at once are handled one after the other.
--
-- Parameters, with the example values used to render this file:
--   $1 = "0199c8a0-0000-7000-8000-00000000000a"
--   $2 = 1
--
-- Generated by `pnpm db:queries` from lib/db/queries/submissions.ts. Do not edit by hand.

select "id", "kind", "status", "target_id", "submitted_by", "required_approvals", "payload"
from "submissions"
where "submissions"."id" = $1
limit $2 for update;
